1	// Package credit 实现本地课程学分与免修的登记、持久化与核对。
2	//
3	// 基本对象：
4	//   - 学生（Student）：以唯一编号登记；
5	//   - 课程（Course）：唯一编号、名称、正整数学分，初始开放，可停开/恢复；
6	//   - 课程要求（Requirement）：属于某名学生，编号在该学生名下唯一，指向一门课程；
7	//   - 修读（Enrollment）：属于某名学生的一项要求，记录学期与编号，结果为
8	//     选课/通过/未通过；
9	//   - 免修（Waiver）：明确指向该学生的一项要求，带编号与非空依据，状态为
10	//     有效/已拒绝/已撤销。
11	//
12	// 所有“重复登记相同内容”的操作都幂等：返回原记录、不新增数据；内容冲突的
13	// 重复请求一律拒绝并保留原记录。
14	package credit
15	
16	import (
17		"errors"
18		"fmt"
19		"strings"
20	)
21	
22	// Result 是修读结果。
23	type Result string
24	
25	const (
26		// Enrolled 已选课、尚未有结果，不计学分。
27		Enrolled Result = "enrolled"
28		// Passed 通过。
29		Passed Result = "passed"
30		// Failed 未通过，不计学分。
31		Failed Result = "failed"
32	)
33	
34	// WaiverStatus 是免修申请的状态。
35	type WaiverStatus string
36	
37	const (
38		// WaiverApproved 有效免修：满足对应要求并获得课程学分。
39		WaiverApproved WaiverStatus = "approved"
40		// WaiverRejected 已拒绝：申请内容与拒绝原因保留在免修历史中。
41		WaiverRejected WaiverStatus = "rejected"
42		// WaiverRevoked 已撤销：原依据保留，要求按修读情况重新判定。
43		WaiverRevoked WaiverStatus = "revoked"
44	)
45	
46	// Course 课程：编号唯一，学分为正整数。
47	type Course struct {
48		ID     string `json:"id"`
49		Name   string `json:"name"`
50		Credit int    `json:"credit"`
51		Open   bool   `json:"open"`
52	}
53	
54	// Student 学生：只有唯一编号。
55	type Student struct {
56		ID string `json:"id"`
57	}
58	
59	// Requirement 课程要求：在所属学生名下编号唯一，指向一门已登记课程。
60	type Requirement struct {
61		ID        string `json:"id"`
62		StudentID string `json:"student"`
63		CourseID  string `json:"course"`
64	}
65	
66	// Enrollment 修读：属于某名学生的一项要求，编号在该学生名下唯一。
67	type Enrollment struct {
68		ID        string `json:"id"`
69		StudentID string `json:"student"`
70		ReqID     string `json:"req"`
71		Term      string `json:"term"`
72		Result    Result `json:"result"`
73		// ResultSeq 是首次提交结果的先后序号，用于确定“最先提交的通过记录”。
74		ResultSeq int `json:"resultSeq,omitempty"`
75	}
76	
77	// Waiver 免修申请。被拒绝或撤销后记录仍保留在免修历史中。
78	type Waiver struct {
79		ID        string       `json:"id"`
80		StudentID string       `json:"student"`
81		ReqID     string       `json:"req"`
82		Basis     string       `json:"basis"`
83		Status    WaiverStatus `json:"status"`
84		// Reason 记录拒绝原因或撤销原因。
85		Reason string `json:"reason,omitempty"`
86	}
87	
88	// Store 是全部记录的内存集合，零值即可用。
89	type Store struct {
90		courses      []*Course
91		students     []*Student
92		requirements []*Requirement
93		enrollments  []*Enrollment
94		waivers      []*Waiver
95	
96		courseByID    map[string]*Course
97		studentByID   map[string]*Student
98		reqByKey      map[string]*Requirement // student + "\x00" + reqID
99		reqByDup      map[string]string       // student + "\x00" + course -> reqID
100		enrByKey      map[string]*Enrollment  // student + "\x00" + enrID
101		waiverByKey   map[string]*Waiver      // student + "\x00" + waiverID
102		nextResultSeq int
103		// dirty 记录自加载以来是否发生过需要落盘的变更（新建被拒绝的免修也算）。
104		dirty bool
105	}
106	
107	func reqKey(student, id string) string { return student + "\x00" + id }
108	func dupKey(student, course string) string {
109		return student + "\x00" + course
110	}
111	
112	func newStore() *Store {
113		s := &Store{}
114		s.resetIndexes()
115		return s
116	}
117	
118	func (s *Store) resetIndexes() {
119		s.courseByID = map[string]*Course{}
120		s.studentByID = map[string]*Student{}
121		s.reqByKey = map[string]*Requirement{}
122		s.reqByDup = map[string]string{}
123		s.enrByKey = map[string]*Enrollment{}
124		s.waiverByKey = map[string]*Waiver{}
125	}
126	
127	// NewStore 返回空记录集。
128	func NewStore() *Store { return newStore() }
129	
130	// Dirty 报告自加载以来是否发生过需要落盘的变更。
131	// 被拒绝但要保留在免修历史中的申请也计为变更；纯幂等返回与只读核对不计。
132	func (s *Store) Dirty() bool { return s.dirty }
133	
134	// ---------- 查询 ----------
135	
136	// Course 按编号返回课程；不存在返回 nil。
137	func (s *Store) Course(id string) *Course { return s.courseByID[id] }
138	
139	// Courses 按登记顺序返回全部课程。
140	func (s *Store) Courses() []*Course { return append([]*Course(nil), s.courses...) }
141	
142	// Student 按编号返回学生；不存在返回 nil。
143	func (s *Store) Student(id string) *Student { return s.studentByID[id] }
144	
145	// Students 按登记顺序返回全部学生。
146	func (s *Store) Students() []*Student { return append([]*Student(nil), s.students...) }
147	
148	// Requirement 返回某学生名下的要求；不存在（包括要求属于其他学生）返回 nil。
149	func (s *Store) Requirement(student, reqID string) *Requirement {
150		return s.reqByKey[reqKey(student, reqID)]
151	}
152	
153	// Requirements 返回某学生的全部要求（按登记顺序）；学生不存在返回 nil。
154	func (s *Store) Requirements(student string) []*Requirement {
155		if _, ok := s.studentByID[student]; !ok {
156			return nil
157		}
158		var out []*Requirement
159		for _, r := range s.requirements {
160			if r.StudentID == student {
161				out = append(out, r)
162			}
163		}
164		return out
165	}
166	
167	// AllRequirements 按登记顺序返回全部要求。
168	func (s *Store) AllRequirements() []*Requirement {
169		return append([]*Requirement(nil), s.requirements...)
170	}
171	
172	// Enrollment 返回某学生名下的修读；不存在返回 nil。
173	func (s *Store) Enrollment(student, id string) *Enrollment {
174		return s.enrByKey[reqKey(student, id)]
175	}
176	
177	// Enrollments 返回某学生的全部修读（按登记顺序）；学生不存在返回 nil。
178	func (s *Store) Enrollments(student string) []*Enrollment {
179		if _, ok := s.studentByID[student]; !ok {
180			return nil
181		}
182		var out []*Enrollment
183		for _, e := range s.enrollments {
184			if e.StudentID == student {
185				out = append(out, e)
186			}
187		}
188		return out
189	}
190	
191	// Waiver 返回某学生名下的免修申请；不存在返回 nil。
192	func (s *Store) Waiver(student, id string) *Waiver {
193		return s.waiverByKey[reqKey(student, id)]
194	}
195	
196	// Waivers 返回某学生的全部免修历史（按申请顺序）；学生不存在返回 nil。
197	func (s *Store) Waivers(student string) []*Waiver {
198		if _, ok := s.studentByID[student]; !ok {
199			return nil
200		}
201		var out []*Waiver
202		for _, w := range s.waivers {
203			if w.StudentID == student {
204				out = append(out, w)
205			}
206		}
207		return out
208	}
209	
210	// ---------- 学生 ----------
211	
212	// AddStudent 登记学生。编号已存在时原样返回已有学生且 action=existed（幂等）。
213	func (s *Store) AddStudent(id string) (st *Student, action Action, err error) {
214		id = strings.TrimSpace(id)
215		if id == "" {
216			return nil, "", errors.New("学生编号不能为空")
217		}
218		if existing := s.studentByID[id]; existing != nil {
219			return existing, ActionExisted, nil
220		}
221		st = &Student{ID: id}
222		s.students = append(s.students, st)
223		s.studentByID[id] = st
224		s.dirty = true
225		return st, ActionCreated, nil
226	}
227	
228	// ---------- 课程 ----------
229	
230	// Action 描述登记类操作相对已有记录做了什么。
231	type Action string
232	
233	const (
234		// ActionCreated 新建了记录。
235		ActionCreated Action = "created"
236		// ActionExisted 记录已存在且内容一致，原样返回（幂等）。
237		ActionExisted Action = "existed"
238		// ActionUpdated 记录已存在，本次在允许范围内更新了内容。
239		ActionUpdated Action = "updated"
240	)
241	
242	// AddCourse 登记课程，学分为正整数，新课程初始开放。
243	// 编号已存在且名称、学分完全相同时原样返回（幂等），停开/开放状态不变。
244	// 编号相同但学分不同：该课程尚未被任何课程要求引用时允许修改并保持开放
245	// 状态；已经被要求引用的课程不能修改学分，请求被拒绝且课程保持不变。
246	func (s *Store) AddCourse(id, name string, credit int) (c *Course, action Action, err error) {
247		id = strings.TrimSpace(id)
248		name = strings.TrimSpace(name)
249		if id == "" {
250			return nil, "", errors.New("课程编号不能为空")
251		}
252		if name == "" {
253			return nil, "", errors.New("课程名称不能为空")
254		}
255		if credit <= 0 {
256			return nil, "", fmt.Errorf("课程学分必须是正整数，得到 %d", credit)
257		}
258		if existing := s.courseByID[id]; existing != nil {
259			if existing.Name == name && existing.Credit == credit {
260				return existing, ActionExisted, nil
261			}
262			if existing.Credit != credit && s.courseReferenced(id) {
263				return nil, "", fmt.Errorf(
264					"课程 %s 已被课程要求引用，不能修改学分（原学分 %d），原记录保留",
265					id, existing.Credit)
266			}
267			existing.Name = name
268			existing.Credit = credit
269			s.dirty = true
270			return existing, ActionUpdated, nil
271		}
272		c = &Course{ID: id, Name: name, Credit: credit, Open: true}
273		s.courses = append(s.courses, c)
274		s.courseByID[id] = c
275		s.dirty = true
276		return c, ActionCreated, nil
277	}
278	
279	// courseReferenced 报告课程是否被任何学生的课程要求引用。
280	func (s *Store) courseReferenced(id string) bool {
281		for _, r := range s.requirements {
282			if r.CourseID == id {
283				return true
284			}
285		}
286		return false
287	}
288	
289	// SetCourseOpen 设置课程开放状态。课程不存在时报错；状态相同则原样返回。
290	func (s *Store) SetCourseOpen(id string, open bool) (*Course, error) {
291		c := s.courseByID[id]
292		if c == nil {
293			return nil, fmt.Errorf("课程 %s 不存在", id)
294		}
295		if c.Open != open {
296			c.Open = open
297			s.dirty = true
298		}
299		return c, nil
300	}
301	
302	// ---------- 课程要求 ----------
303	
304	// AddRequirement 为学生登记一项指向课程的要求。
305	// 同一要求编号已存在且指向同一课程时返回原要求（幂等）；指向不同课程则拒绝。
306	// 同一学生就同一课程已有要求（即使编号不同）也拒绝。学生或课程不存在时拒绝。
307	func (s *Store) AddRequirement(studentID, reqID, courseID string) (r *Requirement, action Action, err error) {
308		studentID = strings.TrimSpace(studentID)
309		reqID = strings.TrimSpace(reqID)
310		courseID = strings.TrimSpace(courseID)
311		if studentID == "" || reqID == "" {
312			return nil, "", errors.New("学生编号和要求编号不能为空")
313		}
314		if _, ok := s.studentByID[studentID]; !ok {
315			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记课程要求", studentID)
316		}
317		c := s.courseByID[courseID]
318		if c == nil {
319			return nil, "", fmt.Errorf("课程 %s 不存在，不能登记课程要求", courseID)
320		}
321		if existing := s.reqByKey[reqKey(studentID, reqID)]; existing != nil {
322			if existing.CourseID != courseID {
323				return nil, "", fmt.Errorf(
324					"学生 %s 的要求编号 %s 已指向课程 %s，不能改指课程 %s",
325					studentID, reqID, existing.CourseID, courseID)
326			}
327			return existing, ActionExisted, nil
328		}
329		if otherID, ok := s.reqByDup[dupKey(studentID, courseID)]; ok {
330			return nil, "", fmt.Errorf(
331				"学生 %s 已就课程 %s 建立要求 %s，不能重复建立", studentID, courseID, otherID)
332		}
333		r = &Requirement{ID: reqID, StudentID: studentID, CourseID: courseID}
334		s.requirements = append(s.requirements, r)
335		s.reqByKey[reqKey(studentID, reqID)] = r
336		s.reqByDup[dupKey(studentID, courseID)] = reqID
337		s.dirty = true
338		return r, ActionCreated, nil
339	}
340	
341	// ---------- 修读 ----------
342	
343	// AddEnrollment 为学生的一项要求登记某学期的修读，初始状态为“选课”。
344	// 相同（学生、修读编号、要求、学期）的重复登记返回原记录（幂等）；
345	// 相同编号但要求或学期不同则拒绝；课程已停开时不能新增修读
346	// （已登记记录的重复提交仍按幂等返回原记录）。
347	func (s *Store) AddEnrollment(studentID, reqID, term, enrID string) (e *Enrollment, action Action, err error) {
348		studentID = strings.TrimSpace(studentID)
349		reqID = strings.TrimSpace(reqID)
350		term = strings.TrimSpace(term)
351		enrID = strings.TrimSpace(enrID)
352		if studentID == "" || reqID == "" || enrID == "" {
353			return nil, "", errors.New("学生编号、要求编号和修读编号不能为空")
354		}
355		if term == "" {
356			return nil, "", errors.New("学期不能为空")
357		}
358		if _, ok := s.studentByID[studentID]; !ok {
359			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记修读", studentID)
360		}
361		r := s.reqByKey[reqKey(studentID, reqID)]
362		if r == nil {
363			return nil, "", fmt.Errorf("学生 %s 名下不存在要求 %s，不能登记修读", studentID, reqID)
364		}
365		if existing := s.enrByKey[reqKey(studentID, enrID)]; existing != nil {
366			if existing.ReqID != reqID || existing.Term != term {
367				return nil, "", fmt.Errorf(
368					"学生 %s 的修读编号 %s 已用于要求 %s、学期 %s，不能改为要求 %s、学期 %s",
369					studentID, enrID, existing.ReqID, existing.Term, reqID, term)
370			}
371			return existing, ActionExisted, nil
372		}
373		c := s.courseByID[r.CourseID]
374		if c == nil || !c.Open {
375			return nil, "", fmt.Errorf("课程 %s 已停开，不能新增修读", r.CourseID)
376		}
377		e = &Enrollment{
378			ID: enrID, StudentID: studentID, ReqID: reqID, Term: term, Result: Enrolled,
379		}
380		s.enrollments = append(s.enrollments, e)
381		s.enrByKey[reqKey(studentID, enrID)] = e
382		s.dirty = true
383		return e, ActionCreated, nil
384	}
385	
386	// SubmitResult 为修读提交通过/未通过结果。
387	// 重复提交相同结果返回原记录（幂等，不累加学分）；已提交结果后改提另一结果
388	// 一律拒绝并保留原记录。
389	func (s *Store) SubmitResult(studentID, enrID string, result Result) (e *Enrollment, changed bool, err error) {
390		studentID = strings.TrimSpace(studentID)
391		enrID = strings.TrimSpace(enrID)
392		if result != Passed && result != Failed {
393			return nil, false, fmt.Errorf("修读结果只能是 %s 或 %s", Passed, Failed)
394		}
395		if _, ok := s.studentByID[studentID]; !ok {
396			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
397		}
398		e = s.enrByKey[reqKey(studentID, enrID)]
399		if e == nil {
400			return nil, false, fmt.Errorf("学生 %s 名下不存在修读 %s", studentID, enrID)
401		}
402		if e.Result == result {
403			return e, false, nil
404		}
405		if e.Result != Enrolled {
406			return nil, false, fmt.Errorf(
407				"修读 %s 已提交结果“%s”，不能改为“%s”，原结果保留", enrID, zhResult(e.Result), zhResult(result))
408		}
409		s.nextResultSeq++
410		e.Result = result
411		e.ResultSeq = s.nextResultSeq
412		s.dirty = true
413		return e, true, nil
414	}
415	
416	// ---------- 免修 ----------
417	
418	// ApplyWaiver 提交免修申请，依据必须非空。
419	//
420	// 首次提交且内容合法：状态为有效（approved），action=created。
421	// 目标要求不存在（含要求属于其他学生）、依据为空、或该要求已有有效免修：
422	// 申请被拒绝，但申请内容与具体原因保留在该学生的免修历史中，
423	// 返回的申请状态为 rejected（仍属于新建记录，action=created）。
424	// 同一编号已存在：内容（要求、依据）完全相同时返回原申请及其结果
425	// （已拒绝/已撤销的申请不会因重试重新生效）；内容不同则拒绝且不改动原申请。
426	func (s *Store) ApplyWaiver(studentID, reqID, waiverID, basis string) (w *Waiver, action Action, err error) {
427		studentID = strings.TrimSpace(studentID)
428		reqID = strings.TrimSpace(reqID)
429		waiverID = strings.TrimSpace(waiverID)
430		basis = strings.TrimSpace(basis)
431		if studentID == "" || reqID == "" || waiverID == "" {
432			return nil, "", errors.New("学生编号、要求编号和免修编号不能为空")
433		}
434		if _, ok := s.studentByID[studentID]; !ok {
435			return nil, "", fmt.Errorf("学生 %s 不存在，不能申请免修", studentID)
436		}
437		if existing := s.waiverByKey[reqKey(studentID, waiverID)]; existing != nil {
438			if existing.ReqID != reqID || existing.Basis != basis {
439				return nil, "", fmt.Errorf(
440					"学生 %s 的免修编号 %s 已存在（要求 %s、依据 %q），提交内容不同，拒绝修改",
441					studentID, waiverID, existing.ReqID, existing.Basis)
442			}
443			return existing, ActionExisted, nil
444		}
445	
446		w = &Waiver{ID: waiverID, StudentID: studentID, ReqID: reqID, Basis: basis}
447		switch {
448		case s.reqByKey[reqKey(studentID, reqID)] == nil:
449			w.Status = WaiverRejected
450			w.Reason = fmt.Sprintf("目标要求 %s 不存在或不属于该学生", reqID)
451		case basis == "":
452			w.Status = WaiverRejected
453			w.Reason = "免修依据为空"
454		default:
455			if other := s.validWaiver(studentID, reqID); other != nil {
456				w.Status = WaiverRejected
457				w.Reason = fmt.Sprintf("该要求已有有效免修 %s", other.ID)
458				break
459			}
460			w.Status = WaiverApproved
461		}
462		s.waivers = append(s.waivers, w)
463		s.waiverByKey[reqKey(studentID, waiverID)] = w
464		s.dirty = true
465		return w, ActionCreated, nil
466	}
467	
468	// validWaiver 返回某要求当前有效的免修。
469	func (s *Store) validWaiver(studentID, reqID string) *Waiver {
470		for _, w := range s.waivers {
471			if w.StudentID == studentID && w.ReqID == reqID && w.Status == WaiverApproved {
472				return w
473			}
474		}
475		return nil
476	}
477	
478	// RevokeWaiver 撤销有效免修，原依据与撤销状态保留；reason 可填撤销原因。
479	// 重复撤销已撤销的免修：原样返回、changed=false，不改变结果。
480	// 撤销不存在的编号或撤销已被拒绝的申请：明确拒绝。
481	func (s *Store) RevokeWaiver(studentID, waiverID, reason string) (w *Waiver, changed bool, err error) {
482		studentID = strings.TrimSpace(studentID)
483		waiverID = strings.TrimSpace(waiverID)
484		reason = strings.TrimSpace(reason)
485		if _, ok := s.studentByID[studentID]; !ok {
486			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
487		}
488		w = s.waiverByKey[reqKey(studentID, waiverID)]
489		if w == nil {
490			return nil, false, fmt.Errorf("学生 %s 名下不存在免修 %s，不能撤销", studentID, waiverID)
491		}
492		switch w.Status {
493		case WaiverApproved:
494			w.Status = WaiverRevoked
495			if reason == "" {
496				reason = "手动撤销"
497			}
498			w.Reason = reason
499			s.dirty = true
500			return w, true, nil
501		case WaiverRevoked:
502			return w, false, nil
503		default:
504			return nil, false, fmt.Errorf("免修 %s 已被拒绝，不能撤销（拒绝原因：%s）", waiverID, w.Reason)
505		}
506	}
507

