303	
304		// 用原编号、原要求、原依据再次提交：返回最初的已拒绝申请，不新增、不改写。
305		for i := 0; i < 2; i++ {
306			w2, a, err := s.ApplyWaiver("s1", "r1", "w1", "学科竞赛获奖")
