311				w2.Reason != origReason {
312				t.Fatalf("目标补建后重复提交不应改变原拒绝结果，得到 %+v", w2)
313			}
314		}
315		if n := len(s.Waivers("s1")); n != 1 {
316			t.Fatalf("重复提交不应新增申请，免修历史应有 1 条，得到 %d", n)
317		}
