321		rep := s.CheckStudent("s1")
322		if rep.TotalCredits != 0 {
323			t.Fatalf("被拒绝的申请不应产生学分，总学分=%d", rep.TotalCredits)
324		}
325		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
326			t.Fatalf("要求 r1 应仍列为未满足，得到 %v", rep.Unmet)
327		}
328		if len(rep.RejectedWaivers) != 1 {
