335		}
336	
337		// 同编号换要求或换依据：按内容冲突拒绝，原申请与原核对结果不变。
338		mustCourse(t, s, "c2", "物理", 3)
339		mustReq(t, s, "s1", "r2", "c2")
340		if _, _, err := s.ApplyWaiver("s1", "r2", "w1", "学科竞赛获奖"); err == nil {
