212		}
213		if strings.Count(out, "免修 w1") != 1 {
214			t.Fatalf("冲突拒绝不应新增申请，out=%q", out)
215		}
216		// 不能改动另一人的同号记录。
217		assertCLIOwnerWaiver(t, file, "s2", "3", "c2", "外校修读证明")
218	
219		// 改用新免修编号 w2 再次取代已经免修的 r1：拒绝（退出码 1），
220		// 并在提交者的历史中留下独立的拒绝记录。
221		out, _, code = runCLI(t, file, "waiver", "s1", "r1", "w2", "再次申请的新依据")
222		if code != 1 || !strings.Contains(out, "免修申请 w2 已拒绝") ||
223			!strings.Contains(out, "该要求已有有效免修 w1") {
224			t.Fatalf("新编号取代已有免修应拒绝并说明已有有效免修 w1，code=%d out=%q", code, out)
225		}
226	
227		// 核对结果应列出这次申请的编号、目标要求、依据，以及已有有效免修的
228		// 具体原因，不能只显示一个没有对应申请的失败提示。
229		out, _, code = runCLI(t, file, "check", "s1")
230		if code != 0 {
231			t.Fatalf("核对本身应成功，code=%d out=%q", code, out)
232		}
233		for _, want := range []string{
234			"被拒绝的免修：",
235			`免修 w2（要求 r1，依据 "再次申请的新依据"）`,
236			"该要求已有有效免修 w1",
237		} {
238			if !strings.Contains(out, want) {
239				t.Fatalf("核对结果应包含 %q，out=%q", want, out)
240			}
241		}
242		// 原有效申请继续作为学分来源，课程学分仍只计一次，要求仍为已满足。
243		if !strings.Contains(out, "总学分：4") ||
244			!strings.Contains(out, "来源为有效免修 w1") ||
245			strings.Contains(out, "未满足要求：[") {
246			t.Fatalf("原 w1 应继续作为唯一学分来源、r1 仍满足，out=%q", out)
247		}
248		out, _, _ = runCLI(t, file, "show", "s1")
249		if !strings.Contains(out, `免修 w1：要求 r1，依据 "学科竞赛获奖"，状态：有效`) ||
250			!strings.Contains(out, `免修 w2：要求 r1，依据 "再次申请的新依据"，状态：已拒绝`) {
251			t.Fatalf("s1 历史应保留独立的 w1 有效与 w2 已拒绝两条，out=%q", out)
252		}
253	
254		// 被拒绝的 w2 原样再次提交：沿用既有幂等行为返回原拒绝记录（退出码 0），
255		// 不新增申请、不生效。
256		out, _, code = runCLI(t, file, "waiver", "s1", "r1", "w2", "再次申请的新依据")
257		if code != 0 || !strings.Contains(out, "内容一致，返回原申请") ||
258			!strings.Contains(out, "状态：已拒绝") {
259			t.Fatalf("w2 重复提交应幂等返回原拒绝记录，code=%d out=%q", code, out)
260		}
261		out, _, _ = runCLI(t, file, "check", "s1")
262		if strings.Count(out, "免修 w2（要求 r1") != 1 || !strings.Contains(out, "总学分：4") {
263			t.Fatalf("w2 重复提交不应新增拒绝记录或改变学分，out=%q", out)
264		}
265	
266		// 另一人的免修历史、有效申请和核对结果始终保持原样。
267		out, _, _ = runCLI(t, file, "show", "s2")
268		if strings.Count(out, "免修 w1") != 1 || strings.Contains(out, "w2") ||
269			strings.Contains(out, "学科竞赛获奖") {
270			t.Fatalf("s2 的历史应始终只有本人的 w1 与本人依据，out=%q", out)
271		}
272		assertCLIOwnerWaiver(t, file, "s2", "3", "c2", "外校修读证明")
273	}
