166		if !strings.Contains(out, "要求 r1（课程 c1《高等数学》，4 学分）：未满足") ||
167			!strings.Contains(out, "总学分：0") {
168			t.Fatalf("拒绝后要求核对仍应显示原名称与原学分，out=%q", out)
169		}
170	
171		// 整单被拒后按原学分只改名称：应成功，证明拒绝没有破坏课程资料。
172		if out, _, code := runCLI(t, file, "course", "c1", "高等数学（下）", "4"); code != 0 {
173			t.Fatalf("相同学分只改名称应成功，code=%d out=%q", code, out)
174		}
175		assertSingleCourseLine(t, file, "课程 c1《高等数学（下）》4 学分，状态：开放", "c1")
176	
177		// 停开不解除学分锁定。
178		if _, errText, code := runCLI(t, file, "course-close", "c1"); code != 0 {
179			t.Fatalf("停开课程失败 code=%d err=%q", code, errText)
180		}
181		closed := mustReadRecord(t, file)
182		if _, errText, code := runCLI(t, file, "course", "c1", "另一个名称", "5"); code != 1 {
183			t.Fatalf("停开不应解除学分锁定，code=%d err=%q", code, errText)
184		}
185		if !strings.Contains(errText, "已被课程要求引用") || !strings.Contains(errText, "原学分 4") {
186			t.Fatalf("停开后拒绝仍应说明被引用与原学分，err=%q", errText)
187		}
188		assertRecordUnchanged(t, file, closed, "停开课程的改学分请求")
189		assertSingleCourseLine(t, file, "课程 c1《高等数学（下）》4 学分，状态：停开", "c1")
190		out, _, _ = runCLI(t, file, "check", "s1")
191		if !strings.Contains(out, "要求 r1（课程 c1《高等数学（下）》，4 学分）：未满足") {
192			t.Fatalf("拒绝后名称与停开状态应保持，out=%q", out)
193		}
194	}
195	
196	// TestCLICourseReregisterReferencedRenameOnlyPreservesRequirementData
197	// 已被要求引用的课程提交新名称但学分与原值相同：允许只改名，课程编号与学分
198	// 不变；课程列表与已有要求查询显示新名称，已有修读与免修继续指向原要求，
199	// 核对的满足情况、学分来源和总学分不变；停开课程改名后仍然停开。
200	func TestCLICourseReregisterReferencedRenameOnlyPreservesRequirementData(t *testing.T) {
201		file := tempRecordFile(t)
202		// s1 以通过修读满足 r1；s2 以有效免修满足同号要求（同一门课程）。
203		for _, st := range [][]string{
204			{"student", "s1"},
205			{"student", "s2"},
206			{"course", "c1", "高等数学", "4"},
207			{"req", "s1", "r1", "c1"},
208			{"enroll", "s1", "r1", "2024春", "e1"},
209			{"pass", "s1", "e1"},
210			{"req", "s2", "r1", "c1"},
211			{"waiver", "s2", "r1", "w1", "外校同层次课程"},
212		} {
213			if _, errText, code := runCLI(t, file, st...); code != 0 {
214				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
215			}
216		}
217		// 改名前先停开，顺带回归“停开课程改名后仍然停开”。
218		if _, errText, code := runCLI(t, file, "course-close", "c1"); code != 0 {
219			t.Fatalf("停开课程失败 code=%d err=%q", code, errText)
220		}
221	
222		// 新名称 + 与原值相同的学分：更新成功（退出码 0）。
223		if out, errText, code := runCLI(t, file, "course", "c1", "高等数学（强化班）", "4"); code != 0 {
224			t.Fatalf("被引用课程相同学分只改名应成功，code=%d out=%q err=%q", code, out, errText)
225		}
226		// 编号与学分不变、名称更新、仍为停开，且只有一份记录。
227		assertSingleCourseLine(t, file, "课程 c1《高等数学（强化班）》4 学分，状态：停开", "c1")
228	
229		// 改名后仍停开：不能新增修读。
230		if _, errText, code := runCLI(t, file, "enroll", "s2", "r1", "2025春", "e9"); code != 1 {
231			t.Fatalf("改名后仍停开的课程不能新增修读，code=%d err=%q", code, errText)
232		}
233	
234		// s1 的已有修读继续指向原要求，核对满足情况、来源与总学分不变，
235		// 只在课程资料处显示新名称。
236		out, _, code := runCLI(t, file, "show", "s1")
237		if code != 0 ||
238			!strings.Contains(out, "要求 r1 -> 课程 c1《高等数学（强化班）》4 学分") ||
239			!strings.Contains(out, "修读 e1：要求 r1，学期 2024春，结果：通过") {
240			t.Fatalf("s1 的要求查询应显示新名称、已有通过修读不变，code=%d out=%q", code, out)
241		}
242		out, _, code = runCLI(t, file, "check", "s1")
243		if code != 0 || !strings.Contains(out, "总学分：4") ||
244			!strings.Contains(out, "要求 r1（课程 c1《高等数学（强化班）》，4 学分）：已满足") ||
245			!strings.Contains(out, "来源为通过修读 e1") ||
246			strings.Contains(out, "未满足要求：[") {
247			t.Fatalf("s1 改名后仍应凭通过修读 e1 满足、总学分 4，out=%q", out)
248		}
249	
250		// s2 的有效免修继续满足原要求，来源与总学分不变，课程显示新名称。
251		out, _, code = runCLI(t, file, "check", "s2")
252		if code != 0 || !strings.Contains(out, "总学分：4") ||
253			!strings.Contains(out, "要求 r1（课程 c1《高等数学（强化班）》，4 学分）：已满足") ||
254			!strings.Contains(out, "来源为有效免修 w1") ||
255			strings.Contains(out, "未满足要求：[") {
256			t.Fatalf("s2 改名后仍应凭有效免修 w1 满足、总学分 4，out=%q", out)
257		}
258		out, _, _ = runCLI(t, file, "show", "s2")
259		if !strings.Contains(out, "要求 r1 -> 课程 c1《高等数学（强化班）》4 学分") ||
260			!strings.Contains(out, `免修 w1：要求 r1，依据 "外校同层次课程"，状态：有效`) {
261			t.Fatalf("s2 的要求应显示新名称且免修记录原样保留，out=%q", out)
262		}
263	}
264	
265	// TestCLICourseReregisterRejectsNonPositiveCreditWithoutSideEffects 课程尚未
266	// 被引用时，零或负数学分同样必须拒绝；拒绝不能顺带改掉名称或开放/停开状态，
267	// 记录文件也不应变化。
268	func TestCLICourseReregisterRejectsNonPositiveCreditWithoutSideEffects(t *testing.T) {
269		file := tempRecordFile(t)
270		if _, errText, code := runCLI(t, file, "course", "c1", "高等数学", "4"); code != 0 {
271			t.Fatalf("登记课程失败 code=%d err=%q", code, errText)
272		}
273	
274		before := mustReadRecord(t, file)
275		for _, credit := range []string{"0", "-3"} {
276			out, errText, code := runCLI(t, file, "course", "c1", "错误名称", credit)
277			if code != 1 || !strings.Contains(errText, "学分") {
278				t.Fatalf("学分 %s 应作为业务规则拒绝（退出码 1），code=%d out=%q err=%q",
279					credit, code, out, errText)
280			}
281			assertRecordUnchanged(t, file, before, "学分为 "+credit+" 的更新请求")
282		}
283		// 名称、学分、开放状态都保持原样，只有一份记录。
284		assertSingleCourseLine(t, file, "课程 c1《高等数学》4 学分，状态：开放", "c1")
285	
286		// 停开状态同样不能被失败请求顺带改掉。
287		if _, errText, code := runCLI(t, file, "course-close", "c1"); code != 0 {
288			t.Fatalf("停开课程失败 code=%d err=%q", code, errText)
289		}
290		closed := mustReadRecord(t, file)
291		if _, errText, code := runCLI(t, file, "course", "c1", "错误名称", "0"); code != 1 {
292			t.Fatalf("停开课程的零学分请求应拒绝，code=%d err=%q", code, errText)
293		}
294		assertRecordUnchanged(t, file, closed, "停开课程的零学分请求")
295		assertSingleCourseLine(t, file, "课程 c1《高等数学》4 学分，状态：停开", "c1")
296	}
