// marshalPreexisting 按记录文件磁盘格式序列化一份预先存在的记录。
func marshalPreexisting(t *testing.T, v map[string]any) []byte {
	t.Helper()
	b, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		t.Fatalf("序列化预置记录失败：%v", err)
	}
	return append(b, '\n')
}

