func writePreexisting(t *testing.T, v map[string]any) (string, []byte) {
	t.Helper()
	raw := marshalPreexisting(t, v)
	file := filepath.Join(t.TempDir(), "records.json")
	if err := os.WriteFile(file, raw, 0o600); err != nil {
		t.Fatalf("写入预置记录失败：%v", err)
